    int largestSubstring = 0;
    for (String str : strings) {
        int len = str.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String substring = str.substring(i, j);
                if (strings.contains(substring) || strings.contains(substring.reverse())) {
                    largestSubstring = Math.max(largestSubstring, substring.length());
                }
            }
        }
    }
    return largestSubstring;
}

